using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence; namespace OrcaFacil.Web.Areas.Admin.Pages.Feedback; [Authorize(Policy="SuperAdmin")] public sealed class IndexModel(OrcaFacilDbContext db):PageModel { public IReadOnlyList<UserFeedback> Items{get;private set;}=[]; public async Task OnGetAsync(string? rating,CancellationToken ct){var q=db.UserFeedback.AsNoTracking().Where(x=>!x.IsDeleted);if(!string.IsNullOrWhiteSpace(rating))q=q.Where(x=>x.Rating==rating);Items=await q.OrderByDescending(x=>x.CreatedAt).Take(300).ToListAsync(ct);} }